head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > captionTitle]<br/>captionAuto=true 일때 caption 값 앞에 추가할 텍스트를 설정합니다.",
    "validation" : [
        "captionAuto=true 일때 caption 값 앞에 추가할 텍스트를 설정합니다.",
        "자동으로 생성된 caption 값 앞에 추가할 제목 텍스트를 설정합니다.",
        "자동 생성되는 caption 값은 '{captionTitle}은(는) {Header 값 조합} 을(를) 나타낸 표.' 가 됩니다.",
        "accessibility=true 이면 shortcut 안내 문구가 추가되어 '{captionTitle}은(는) {Header 값 조합} 을(를) 나타낸 표. CTRL 키와 END 키를 동시에 누르면 포커스가 테이블의 마지막 셀로 이동합니다.' 가 됩니다.",
        "setCaptionAuto() 메소드로 caption 값을 자동 생성 시 accessibility=true 여도 shortcut 안내 문구는 생성되지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 라벨 생성
    $c.gcm.createLabel('label="Header 값: 사번 / 이름 / 부서 / 직급"', '', 'label1');

    // dataList 생성
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // 조건 설정 - captionTitle / captionAuto / accessibility
    let captionTitleText  = con_captionTitle.getValue();
    let captionAutoText   = con_captionAuto.getText();
    let accessibilityText = con_accessibility.getText();

    // target 생성 (Header 값을 의미있는 한글 라벨로 구성한 custom gridView)
    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    let captionTitleAttr  = captionTitleText  === '' ? '' : 'captionTitle="'  + captionTitleText  + '" ';
    let captionAutoAttr   = captionAutoText   === '' ? '' : 'captionAuto="'   + captionAutoText   + '" ';
    let accessibilityAttr = accessibilityText === '' ? '' : 'accessibility="' + accessibilityText + '" ';

    strTarget += '<w2:gridView ' + strNameSpace + ' ' + captionTitleAttr + captionAutoAttr + accessibilityAttr + 'dataList="data:dlt_bind" checkAllType="false" id="" style="width:600px;height:200px;">';
    strTarget += '<w2:caption style="" id="caption1" value="디자인 시 정의된 GridViewCaption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="120" inputType="text" id="column1" value="사번"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="column2" value="이름"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="column3" value="부서"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="column4" value="직급"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="120" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 공통: caption 값 출력
scwin.getCaptionText = function () {
    let captionEl = document.querySelector("#" + target1.id + "_body_table caption");
    return captionEl ? captionEl.innerHTML : "";
}



// 1) 현재 caption 확인 (captionTitle 적용 결과)
scwin.btn_getCaption_onclick = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("caption : " + scwin.getCaptionText());
}

// 2) setCaptionAuto() 호출 후 caption 재확인
// - accessibility=true 여도 shortcut 안내 문구가 생성되지 않는지 확인 (@spec)
scwin.btn_setCaptionAuto_onclick = function () {
    target1.setCaptionAuto();
    wf_body_bottom.getObj("scwin").setReturnValue("caption : " + scwin.getCaptionText());
}
